BEGIN;
CREATE TABLE public.maintenance_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),kind text NOT NULL CHECK(kind IN ('pneu','implemento')),code text NOT NULL CHECK(length(btrim(code)) BETWEEN 1 AND 80),description text NOT NULL CHECK(length(btrim(description)) BETWEEN 1 AND 500),brand text NOT NULL DEFAULT '',model text NOT NULL DEFAULT '',size text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'estoque' CHECK(status IN ('estoque','instalado','recapagem','manutencao','descartado')),vehicle_id uuid,position text,last_km integer NOT NULL DEFAULT 0 CHECK(last_km>=0),installed_km integer,retreads integer NOT NULL DEFAULT 0 CHECK(retreads>=0),acquisition_cost numeric(14,2) NOT NULL DEFAULT 0 CHECK(acquisition_cost>=0),interval_km integer CHECK(interval_km>0),interval_days integer CHECK(interval_days>0),last_service_km integer,last_service_date date,version integer NOT NULL DEFAULT 1,created_by uuid NOT NULL REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,company_id),UNIQUE(company_id,kind,code),FOREIGN KEY(vehicle_id,company_id) REFERENCES public.veiculos(id,company_id),CHECK((status='instalado')=(vehicle_id IS NOT NULL)),CHECK(status<>'instalado' OR nullif(btrim(position),'') IS NOT NULL));
CREATE UNIQUE INDEX maintenance_asset_tire_position ON public.maintenance_assets(company_id,vehicle_id,lower(position)) WHERE kind='pneu' AND status='instalado';
CREATE INDEX maintenance_asset_company ON public.maintenance_assets(company_id,kind);CREATE INDEX maintenance_asset_vehicle ON public.maintenance_assets(vehicle_id,company_id);CREATE INDEX maintenance_asset_creator ON public.maintenance_assets(created_by);
CREATE TABLE public.maintenance_asset_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),asset_id uuid NOT NULL,action text NOT NULL,description text NOT NULL,km integer CHECK(km>=0),cost numeric(14,2) NOT NULL DEFAULT 0 CHECK(cost>=0),vehicle_id uuid,position text,actor_id uuid NOT NULL REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),FOREIGN KEY(asset_id,company_id) REFERENCES public.maintenance_assets(id,company_id),FOREIGN KEY(vehicle_id,company_id) REFERENCES public.veiculos(id,company_id));
CREATE INDEX maintenance_asset_event_asset ON public.maintenance_asset_events(asset_id,company_id,created_at DESC);CREATE INDEX maintenance_asset_event_company ON public.maintenance_asset_events(company_id);CREATE INDEX maintenance_asset_event_vehicle ON public.maintenance_asset_events(vehicle_id,company_id);CREATE INDEX maintenance_asset_event_actor ON public.maintenance_asset_events(actor_id);
CREATE TABLE public.maintenance_checklists(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),request_id uuid NOT NULL,vehicle_id uuid NOT NULL,driver_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('saida','retorno')),km integer NOT NULL CHECK(km>=0),items jsonb NOT NULL,notes text NOT NULL DEFAULT '',severity text CHECK(severity IN ('leve','media','urgente')),report_id uuid,created_by uuid NOT NULL REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(company_id,request_id),FOREIGN KEY(vehicle_id,company_id) REFERENCES public.veiculos(id,company_id),FOREIGN KEY(driver_id,company_id) REFERENCES public.motoristas(id,company_id),FOREIGN KEY(report_id,company_id) REFERENCES public.maintenance_driver_reports(id,company_id));
CREATE INDEX maintenance_checklist_company ON public.maintenance_checklists(company_id,created_at DESC);CREATE INDEX maintenance_checklist_vehicle ON public.maintenance_checklists(vehicle_id,company_id);CREATE INDEX maintenance_checklist_driver ON public.maintenance_checklists(driver_id,company_id);CREATE INDEX maintenance_checklist_report ON public.maintenance_checklists(report_id,company_id);CREATE INDEX maintenance_checklist_creator ON public.maintenance_checklists(created_by);
CREATE TABLE public.maintenance_warranty_claims(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),item_id uuid NOT NULL,description text NOT NULL CHECK(length(btrim(description)) BETWEEN 5 AND 4000),status text NOT NULL DEFAULT 'aberta' CHECK(status IN ('aberta','em_analise','aceita','recusada','resolvida')),response text NOT NULL DEFAULT '',version integer NOT NULL DEFAULT 1,created_by uuid NOT NULL REFERENCES auth.users(id),updated_by uuid NOT NULL REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(item_id,company_id) REFERENCES public.maintenance_order_items(id,company_id));
CREATE INDEX maintenance_warranty_company ON public.maintenance_warranty_claims(company_id);CREATE INDEX maintenance_warranty_item ON public.maintenance_warranty_claims(item_id,company_id);CREATE INDEX maintenance_warranty_creator ON public.maintenance_warranty_claims(created_by);CREATE INDEX maintenance_warranty_updater ON public.maintenance_warranty_claims(updated_by);
CREATE TABLE public.maintenance_operations_audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),entity_id uuid NOT NULL,action text NOT NULL,details jsonb NOT NULL,actor_id uuid NOT NULL REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp());CREATE INDEX maintenance_operations_audit_company ON public.maintenance_operations_audit(company_id,created_at DESC);CREATE INDEX maintenance_operations_audit_actor ON public.maintenance_operations_audit(actor_id);
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['maintenance_assets','maintenance_asset_events','maintenance_checklists','maintenance_warranty_claims','maintenance_operations_audit'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated',t);EXECUTE format('GRANT SELECT ON public.%I TO authenticated',t);EXECUTE format('CREATE POLICY company_read ON public.%I FOR SELECT TO authenticated USING(maintenance_private.partner_access(company_id))',t);END LOOP;END $$;
CREATE VIEW public.maintenance_warranty_register WITH(security_invoker=true) AS SELECT i.id,i.company_id,i.order_id,i.descricao,i.tipo,i.garantia_dias,o.vehicle_id,o.partner_id,o.numero,v.placa,p.nome_fantasia,coalesce(o.data_saida_oficina,o.encerrada_em) AS start_at,(coalesce(o.data_saida_oficina,o.encerrada_em) AT TIME ZONE 'America/Sao_Paulo')::date+i.garantia_dias AS expires_on FROM public.maintenance_order_items i JOIN public.maintenance_orders o ON o.id=i.order_id AND o.company_id=i.company_id JOIN public.veiculos v ON v.id=o.vehicle_id AND v.company_id=o.company_id JOIN public.maintenance_partners p ON p.id=o.partner_id AND p.company_id=o.company_id WHERE i.garantia_dias>0 AND o.status IN ('veiculo_retirado','encerrada');GRANT SELECT ON public.maintenance_warranty_register TO authenticated;
CREATE FUNCTION maintenance_private.nonnegative_amount(value text) RETURNS numeric LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$ BEGIN IF coalesce(value,'')!~'^[0-9]{1,12}([.][0-9]{1,2})?$' THEN RAISE EXCEPTION 'Informe valor não negativo com até duas casas decimais.';END IF;RETURN value::numeric;END $$;REVOKE ALL ON FUNCTION maintenance_private.nonnegative_amount(text) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION maintenance_private.operations(c uuid,action text,b jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE a public.maintenance_assets;v public.veiculos;d public.motoristas;result jsonb;target uuid;reading integer;cost_value numeric;event text;row_item jsonb;defect_count integer:=0;report uuid;clean jsonb:='{}';check_keys text[]:=ARRAY['pneus','freios','iluminacao','fluidos','direcao','documentos','equipamentos'];key text;claim public.maintenance_warranty_claims;
BEGIN
IF auth.uid() IS NULL OR NOT maintenance_private.partner_access(c) THEN RAISE EXCEPTION 'Acesso não autorizado.' USING ERRCODE='42501';END IF;
IF action='list_assets' THEN RETURN coalesce((SELECT jsonb_agg(to_jsonb(x)||jsonb_build_object('placa',fleet.placa,'custo_acumulado',x.acquisition_cost+coalesce((SELECT sum(e.cost) FROM public.maintenance_asset_events e WHERE e.asset_id=x.id AND e.company_id=c),0),'events',coalesce((SELECT jsonb_agg(to_jsonb(e) ORDER BY e.created_at DESC) FROM public.maintenance_asset_events e WHERE e.asset_id=x.id AND e.company_id=c),'[]')) ORDER BY x.code) FROM public.maintenance_assets x LEFT JOIN public.veiculos fleet ON fleet.id=x.vehicle_id AND fleet.company_id=c WHERE x.company_id=c AND x.kind=b->>'kind'),'[]');END IF;
IF action='checklists' THEN RETURN coalesce((SELECT jsonb_agg(to_jsonb(x)||jsonb_build_object('placa',fleet.placa,'motorista',driver_registry.nome) ORDER BY x.created_at DESC) FROM (SELECT * FROM public.maintenance_checklists WHERE company_id=c ORDER BY created_at DESC LIMIT 200) x JOIN public.veiculos fleet ON fleet.id=x.vehicle_id AND fleet.company_id=c JOIN public.motoristas driver_registry ON driver_registry.id=x.driver_id AND driver_registry.company_id=c),'[]');END IF;
IF action='warranties' THEN RETURN jsonb_build_object('items',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.expires_on) FROM public.maintenance_warranty_register x WHERE company_id=c),'[]'),'claims',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM public.maintenance_warranty_claims x WHERE company_id=c),'[]'),'recurrences',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT fleet.id,fleet.placa,count(o.id) AS ordens,min(o.data_abertura) AS primeira,max(o.data_abertura) AS ultima FROM public.veiculos fleet JOIN public.maintenance_orders o ON o.vehicle_id=fleet.id AND o.company_id=fleet.company_id WHERE fleet.company_id=c AND o.tipo='corretiva' AND o.status<>'cancelada' AND o.data_abertura>=clock_timestamp()-interval '90 days' GROUP BY fleet.id,fleet.placa HAVING count(o.id)>1 ORDER BY count(o.id) DESC LIMIT 50) x),'[]'));END IF;
IF action='deliveries' THEN RETURN coalesce((SELECT jsonb_agg(to_jsonb(x)-'claim_token' ORDER BY x.created_at DESC) FROM (SELECT * FROM public.maintenance_delivery_jobs WHERE company_id=c ORDER BY created_at DESC LIMIT 200) x),'[]');END IF;
IF NOT maintenance_private.partner_access(c,true) THEN RAISE EXCEPTION 'Sem permissão para alterar.' USING ERRCODE='42501';END IF;
IF action='asset_create' THEN
IF b->>'kind' NOT IN ('pneu','implemento') OR length(btrim(coalesce(b->>'code',''))) NOT BETWEEN 1 AND 80 OR length(btrim(coalesce(b->>'description',''))) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'Informe identificação e descrição.';END IF;
cost_value:=maintenance_private.nonnegative_amount(coalesce(b->>'acquisition_cost','0'));
INSERT INTO public.maintenance_assets(company_id,kind,code,description,brand,model,size,acquisition_cost,interval_km,interval_days,last_service_km,last_service_date,created_by) VALUES(c,b->>'kind',btrim(b->>'code'),btrim(b->>'description'),left(coalesce(b->>'brand',''),100),left(coalesce(b->>'model',''),100),left(coalesce(b->>'size',''),60),cost_value,nullif(b->>'interval_km','')::integer,nullif(b->>'interval_days','')::integer,nullif(b->>'last_service_km','')::integer,nullif(b->>'last_service_date','')::date,auth.uid()) RETURNING * INTO a;
INSERT INTO public.maintenance_asset_events(company_id,asset_id,action,description,actor_id) VALUES(c,a.id,'cadastro','Ativo cadastrado',auth.uid());result:=to_jsonb(a);target:=a.id;
ELSIF action='asset_event' THEN
SELECT * INTO a FROM public.maintenance_assets WHERE id=(b->>'id')::uuid AND company_id=c FOR UPDATE;IF NOT FOUND OR a.version IS DISTINCT FROM (b->>'version')::integer THEN RAISE EXCEPTION 'Ativo alterado ou indisponível. Atualize.';END IF;
event:=b->>'event';reading:=nullif(b->>'km','')::integer;cost_value:=maintenance_private.nonnegative_amount(coalesce(nullif(b->>'cost',''),'0'));
IF a.status='descartado' OR event NOT IN ('instalar','remover','recapagem','retorno_recapagem','manutencao','revisao','leitura','descartar') OR length(btrim(coalesce(b->>'description',''))) NOT BETWEEN 5 AND 2000 THEN RAISE EXCEPTION 'Revise a movimentação e observação.';END IF;
IF event='instalar' THEN
IF a.status<>'estoque' OR nullif(btrim(b->>'position'),'') IS NULL THEN RAISE EXCEPTION 'Somente ativos em estoque podem ser instalados. Informe posição.';END IF;
SELECT * INTO v FROM public.veiculos WHERE id=(b->>'vehicle_id')::uuid AND company_id=c FOR UPDATE;IF NOT FOUND OR reading IS NULL OR reading<v.km_atual THEN RAISE EXCEPTION 'Selecione veículo e KM igual ou superior ao odômetro atual.';END IF;
UPDATE public.maintenance_assets SET status='instalado',vehicle_id=v.id,position=left(btrim(b->>'position'),80),installed_km=reading,last_km=reading,version=version+1 WHERE id=a.id RETURNING * INTO a;
ELSIF event IN ('remover','leitura') THEN
IF a.status<>'instalado' THEN RAISE EXCEPTION 'O ativo precisa estar instalado.';END IF;
SELECT * INTO v FROM public.veiculos WHERE id=a.vehicle_id AND company_id=c FOR UPDATE;IF reading IS NULL OR reading<greatest(v.km_atual,a.last_km) THEN RAISE EXCEPTION 'O odômetro não pode diminuir.';END IF;
UPDATE public.maintenance_assets SET status=CASE WHEN event='remover' THEN 'estoque' ELSE status END,vehicle_id=CASE WHEN event='remover' THEN NULL ELSE vehicle_id END,position=CASE WHEN event='remover' THEN NULL ELSE position END,last_km=reading,version=version+1 WHERE id=a.id RETURNING * INTO a;
ELSIF event='recapagem' THEN
IF a.kind<>'pneu' OR a.status<>'estoque' THEN RAISE EXCEPTION 'Retire o pneu do veículo antes de enviar à recapagem.';END IF;UPDATE public.maintenance_assets SET status='recapagem',version=version+1 WHERE id=a.id RETURNING * INTO a;
ELSIF event='retorno_recapagem' THEN IF a.kind<>'pneu' OR a.status<>'recapagem' THEN RAISE EXCEPTION 'Pneu não está em recapagem.';END IF;UPDATE public.maintenance_assets SET status='estoque',retreads=retreads+1,version=version+1 WHERE id=a.id RETURNING * INTO a;
ELSIF event='manutencao' THEN IF a.status<>'estoque' THEN RAISE EXCEPTION 'Desvincule o implemento para manutenção.';END IF;UPDATE public.maintenance_assets SET status='manutencao',version=version+1 WHERE id=a.id RETURNING * INTO a;
ELSIF event='revisao' THEN IF reading IS NULL OR reading<coalesce(a.last_service_km,0) THEN RAISE EXCEPTION 'Informe KM válido da revisão.';END IF;UPDATE public.maintenance_assets SET status=CASE WHEN status='manutencao' THEN 'estoque' ELSE status END,last_service_date=(clock_timestamp() AT TIME ZONE 'America/Sao_Paulo')::date,last_service_km=reading,version=version+1 WHERE id=a.id RETURNING * INTO a;
ELSIF event='descartar' THEN IF a.vehicle_id IS NOT NULL THEN RAISE EXCEPTION 'Remova o ativo do veículo antes de descartar.';END IF;UPDATE public.maintenance_assets SET status='descartado',version=version+1 WHERE id=a.id RETURNING * INTO a;END IF;
IF v.id IS NOT NULL THEN UPDATE public.veiculos SET km_atual=reading WHERE id=v.id AND company_id=c AND km_atual<reading;END IF;
INSERT INTO public.maintenance_asset_events(company_id,asset_id,action,description,km,cost,vehicle_id,position,actor_id) VALUES(c,a.id,event,btrim(b->>'description'),reading,cost_value,coalesce(v.id,a.vehicle_id),coalesce(b->>'position',a.position),auth.uid());result:=to_jsonb(a);target:=a.id;
ELSIF action='checklist_create' THEN
SELECT to_jsonb(x) INTO result FROM public.maintenance_checklists x WHERE company_id=c AND request_id=(b->>'request_id')::uuid;IF FOUND THEN RETURN result;END IF;
SELECT * INTO v FROM public.veiculos WHERE id=(b->>'vehicle_id')::uuid AND company_id=c FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Veículo indisponível.';END IF;
SELECT * INTO d FROM public.motoristas WHERE id=(b->>'driver_id')::uuid AND company_id=c;IF NOT FOUND THEN RAISE EXCEPTION 'Motorista indisponível.';END IF;
reading:=(b->>'km')::integer;IF reading IS NULL OR reading<v.km_atual OR reading>10000000 OR b->>'kind' NOT IN ('saida','retorno') THEN RAISE EXCEPTION 'Revise tipo e KM do checklist.';END IF;
FOREACH key IN ARRAY check_keys LOOP IF coalesce(b->'items'->>key,'') NOT IN ('ok','defeito','nao_aplicavel') THEN RAISE EXCEPTION 'Preencha todos os itens do checklist.';END IF;clean:=clean||jsonb_build_object(key,b->'items'->>key);IF b->'items'->>key='defeito' THEN defect_count:=defect_count+1;END IF;END LOOP;
IF defect_count>0 THEN
IF length(btrim(coalesce(b->>'notes',''))) NOT BETWEEN 5 AND 10000 OR coalesce(b->>'severity','') NOT IN ('leve','media','urgente') THEN RAISE EXCEPTION 'Descreva os defeitos e indique a prioridade.';END IF;
INSERT INTO public.maintenance_driver_reports(company_id,request_id,driver_id,vehicle_id,driver_name,vehicle_plate,km,defects,severity,vehicle_snapshot) VALUES(c,(b->>'request_id')::uuid,d.id,v.id,d.nome,v.placa,reading,'Checklist '||(b->>'kind')||': '||btrim(b->>'notes'),b->>'severity',to_jsonb(v)-'renavam') RETURNING id INTO report;
INSERT INTO public.maintenance_driver_report_events(company_id,report_id,action,message,actor_id) VALUES(c,report,'checklist','Defeito reportado em checklist de '||(b->>'kind'),auth.uid());END IF;
INSERT INTO public.maintenance_checklists(company_id,request_id,vehicle_id,driver_id,kind,km,items,notes,severity,report_id,created_by) VALUES(c,(b->>'request_id')::uuid,v.id,d.id,b->>'kind',reading,clean,left(coalesce(b->>'notes',''),10000),CASE WHEN defect_count>0 THEN b->>'severity' END,report,auth.uid()) RETURNING id INTO target;
UPDATE public.veiculos SET km_atual=reading WHERE id=v.id AND company_id=c AND km_atual<reading;SELECT to_jsonb(x) INTO result FROM public.maintenance_checklists x WHERE id=target;
ELSIF action='warranty_claim' THEN
IF NOT EXISTS(SELECT 1 FROM public.maintenance_warranty_register WHERE id=(b->>'item_id')::uuid AND company_id=c) THEN RAISE EXCEPTION 'Item sem garantia registrada.';END IF;
INSERT INTO public.maintenance_warranty_claims(company_id,item_id,description,created_by,updated_by) VALUES(c,(b->>'item_id')::uuid,btrim(b->>'description'),auth.uid(),auth.uid()) RETURNING * INTO claim;result:=to_jsonb(claim);target:=claim.id;
ELSIF action='warranty_status' THEN
SELECT * INTO claim FROM public.maintenance_warranty_claims WHERE id=(b->>'id')::uuid AND company_id=c FOR UPDATE;IF NOT FOUND OR claim.version IS DISTINCT FROM (b->>'version')::integer OR length(btrim(coalesce(b->>'response','')))<5 THEN RAISE EXCEPTION 'Atualize os dados e registre a resposta.';END IF;
UPDATE public.maintenance_warranty_claims SET status=b->>'status',response=left(btrim(b->>'response'),4000),version=version+1,updated_by=auth.uid(),updated_at=clock_timestamp() WHERE id=claim.id RETURNING * INTO claim;result:=to_jsonb(claim);target:=claim.id;
ELSE RAISE EXCEPTION 'Ação inválida.';END IF;
INSERT INTO public.maintenance_operations_audit(company_id,entity_id,action,details,actor_id) VALUES(c,target,action,result,auth.uid());RETURN result;
END $$;
REVOKE ALL ON FUNCTION maintenance_private.operations(uuid,text,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION maintenance_private.operations(uuid,text,jsonb) TO authenticated;
CREATE FUNCTION public.maintenance_operations(target_company uuid,command text,body jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$ SELECT maintenance_private.operations(target_company,command,body);$$;
REVOKE ALL ON FUNCTION public.maintenance_operations(uuid,text,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.maintenance_operations(uuid,text,jsonb) TO authenticated;
CREATE FUNCTION maintenance_private.cashflow(c uuid,b jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE start_date date:=coalesce(nullif(b->>'start','')::date,date_trunc('year',current_date)::date);end_date date:=coalesce(nullif(b->>'end','')::date,current_date+interval '1 year');BEGIN
IF auth.uid() IS NULL OR NOT maintenance_private.partner_access(c) THEN RAISE EXCEPTION 'Acesso não autorizado.' USING ERRCODE='42501';END IF;
IF end_date<start_date OR end_date-start_date>3660 THEN RAISE EXCEPTION 'Período inválido (máximo 10 anos).';END IF;
RETURN coalesce((WITH invoices AS(SELECT i.*,o.vehicle_id FROM public.maintenance_finance_invoices i JOIN public.maintenance_orders o ON o.id=i.order_id AND o.company_id=i.company_id WHERE i.company_id=c AND i.status<>'cancelada' AND (nullif(b->>'vehicle_id','') IS NULL OR o.vehicle_id=(b->>'vehicle_id')::uuid) AND (nullif(b->>'partner_id','') IS NULL OR i.partner_id=(b->>'partner_id')::uuid)),forecast AS(SELECT date_trunc('month',s.vencimento)::date AS month,sum(s.valor) AS value FROM public.maintenance_finance_installments s JOIN invoices i ON i.id=s.invoice_id AND i.company_id=s.company_id WHERE s.company_id=c AND s.vencimento BETWEEN start_date AND end_date GROUP BY 1),actual AS(SELECT date_trunc('month',p.data_pagamento)::date AS month,sum(CASE WHEN p.tipo='pagamento' THEN p.valor ELSE -p.valor END) AS value FROM public.maintenance_finance_payments p JOIN public.maintenance_finance_installments s ON s.id=p.installment_id AND s.company_id=p.company_id JOIN invoices i ON i.id=s.invoice_id AND i.company_id=s.company_id WHERE p.company_id=c AND p.data_pagamento BETWEEN start_date AND end_date GROUP BY 1),months AS(SELECT generate_series(date_trunc('month',start_date),date_trunc('month',end_date),interval '1 month')::date AS month) SELECT jsonb_agg(jsonb_build_object('mes',m.month,'previsto',coalesce(f.value,0),'realizado',coalesce(a.value,0),'diferenca',coalesce(a.value,0)-coalesce(f.value,0)) ORDER BY m.month) FROM months m LEFT JOIN forecast f USING(month) LEFT JOIN actual a USING(month)),'[]');END $$;
REVOKE ALL ON FUNCTION maintenance_private.cashflow(uuid,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION maintenance_private.cashflow(uuid,jsonb) TO authenticated;
CREATE FUNCTION public.maintenance_cashflow(target_company uuid,body jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$ SELECT maintenance_private.cashflow(target_company,body);$$;
REVOKE ALL ON FUNCTION public.maintenance_cashflow(uuid,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.maintenance_cashflow(uuid,jsonb) TO authenticated;
DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('maintenance_private.quote_admin(uuid,text,jsonb)'::regprocedure) INTO def;def:=replace(def,'UPDATE public.maintenance_orders SET prazo_entrega_dias=q.delivery_days', 'UPDATE public.maintenance_order_items SET garantia_dias=q.warranty_days WHERE order_id=q.order_id AND company_id=c; UPDATE public.maintenance_orders SET prazo_entrega_dias=q.delivery_days');EXECUTE def;END $$;

ALTER TABLE public.maintenance_checklists ADD COLUMN verified_driver boolean NOT NULL DEFAULT false;
ALTER TABLE public.maintenance_checklists ALTER COLUMN created_by DROP NOT NULL;
ALTER TABLE public.maintenance_checklists ADD CONSTRAINT checklist_author CHECK(created_by IS NOT NULL OR verified_driver);
DO $migration$ DECLARE def text;BEGIN SELECT pg_get_functiondef('driver_portal_private.gateway(text,text,jsonb)'::regprocedure) INTO def;
def:=replace(def,'phone text;created boolean:=false;','phone text;created boolean:=false;check_result jsonb;check_item text;check_defect boolean:=false;check_row public.maintenance_checklists;');
IF position('IF action=''home'' THEN' in def)=0 THEN RAISE EXCEPTION 'Contrato do portal não encontrado';END IF;
def:=replace(def,'IF action=''home'' THEN',$patch$
IF action='checklist' THEN
SELECT * INTO check_row FROM public.maintenance_checklists WHERE company_id=inv.company_id AND request_id=(b->>'request_id')::uuid;
IF FOUND THEN IF check_row.driver_id<>d.id THEN RAISE EXCEPTION 'Solicitação inválida.';END IF;RETURN jsonb_build_object('checklist_id',check_row.id,'report_id',check_row.report_id);END IF;
IF (SELECT count(*) FROM public.maintenance_checklists WHERE driver_id=d.id AND created_at>clock_timestamp()-interval '1 hour')>=20 THEN RAISE EXCEPTION 'Limite de checklists atingido. Aguarde.';END IF;
SELECT * INTO v FROM public.veiculos WHERE id=(b->>'vehicle_id')::uuid AND company_id=inv.company_id FOR UPDATE;
IF NOT FOUND OR coalesce(b->>'km','')!~'^[0-9]{1,8}$' OR (b->>'km')::integer<coalesce(v.km_atual,0) OR (b->>'km')::integer>10000000 OR coalesce(b->>'kind','') NOT IN ('saida','retorno') THEN RAISE EXCEPTION 'Revise placa, KM e tipo do checklist.';END IF;
FOREACH check_item IN ARRAY ARRAY['pneus','freios','iluminacao','fluidos','direcao','documentos','equipamentos'] LOOP
IF coalesce(b->'items'->>check_item,'') NOT IN ('ok','defeito','nao_aplicavel') THEN RAISE EXCEPTION 'Verifique todos os itens.';END IF;
IF b->'items'->>check_item='defeito' THEN check_defect:=true;END IF;END LOOP;
IF check_defect AND length(btrim(coalesce(b->>'notes','')))<5 THEN RAISE EXCEPTION 'Descreva os defeitos em pelo menos cinco caracteres.';END IF;
IF check_defect THEN check_result:=driver_portal_private.gateway(server_key,'submit',b||jsonb_build_object('defects','Checklist '||(b->>'kind')||': '||coalesce(b->>'notes','')));END IF;
INSERT INTO public.maintenance_checklists(company_id,request_id,vehicle_id,driver_id,kind,km,items,notes,severity,report_id,verified_driver,created_by) VALUES(inv.company_id,(b->>'request_id')::uuid,v.id,d.id,b->>'kind',(b->>'km')::integer,b->'items',left(coalesce(b->>'notes',''),10000),CASE WHEN check_defect THEN b->>'severity' END,(check_result->>'id')::uuid,true,NULL) RETURNING * INTO check_row;
UPDATE public.veiculos SET km_atual=check_row.km WHERE id=v.id AND company_id=inv.company_id AND km_atual<check_row.km;
RETURN jsonb_build_object('checklist_id',check_row.id,'report_id',check_row.report_id);END IF;
IF action='home' THEN$patch$);EXECUTE def;END $migration$;

CREATE FUNCTION maintenance_private.asset_distance(target uuid,c uuid) RETURNS numeric LANGUAGE sql STABLE SET search_path='' AS $$
WITH history AS(SELECT action,km,vehicle_id,created_at,id FROM public.maintenance_asset_events WHERE asset_id=target AND company_id=c),closed AS(SELECT sum(greatest(0,e.km-(SELECT i.km FROM history i WHERE i.action='instalar' AND (i.created_at,i.id)<(e.created_at,e.id) ORDER BY i.created_at DESC,i.id DESC LIMIT 1))) AS km FROM history e WHERE e.action='remover'),current_use AS(SELECT CASE WHEN a.status='instalado' THEN greatest(0,coalesce(v.km_atual,a.last_km)-a.installed_km) ELSE 0 END AS km FROM public.maintenance_assets a LEFT JOIN public.veiculos v ON v.id=a.vehicle_id AND v.company_id=a.company_id WHERE a.id=target AND a.company_id=c)
SELECT coalesce((SELECT km FROM closed),0)+coalesce((SELECT km FROM current_use),0);$$;
REVOKE ALL ON FUNCTION maintenance_private.asset_distance(uuid,uuid) FROM PUBLIC,anon,authenticated;
DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('maintenance_private.operations(uuid,text,jsonb)'::regprocedure) INTO def;def:=replace(def,'''custo_acumulado'',x.acquisition_cost','''km_acumulado'',maintenance_private.asset_distance(x.id,c),''custo_acumulado'',x.acquisition_cost');EXECUTE def;
SELECT pg_get_functiondef('maintenance_private.order_command(uuid,text,jsonb)'::regprocedure) INTO def;
IF position('UPDATE public.maintenance_orders SET decisao_por=NULL,decisao_em=NULL WHERE id=o.id;' in def)=0 THEN RAISE EXCEPTION 'Contrato de garantia do item não encontrado';END IF;
def:=replace(def,'UPDATE public.maintenance_orders SET decisao_por=NULL,decisao_em=NULL WHERE id=o.id;',$patch$
IF action='item_save' AND payload ? 'garantia_dias' THEN IF coalesce(payload->>'garantia_dias','')!~'^[0-9]{1,4}$' OR (payload->>'garantia_dias')::integer>3650 THEN RAISE EXCEPTION 'Garantia deve ser entre zero e 3650 dias.';END IF;UPDATE public.maintenance_order_items SET garantia_dias=(payload->>'garantia_dias')::integer WHERE id=item.id AND company_id=c;END IF;
UPDATE public.maintenance_orders SET decisao_por=NULL,decisao_em=NULL WHERE id=o.id;$patch$);EXECUTE def;END $$;
COMMIT;
